// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }

    function testFuzz_property(uint256 v, bool initFirst) public {

        if (initFirst) {
            c.Initialized();
        }

        bool ok;
        try c.SetMinSum(v) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.MinSum() == v);
        } else {
            assertTrue(ok == false ? c.MinSum() == c.MinSum() : c.MinSum() == v);
        }
    }
}
